&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;e3082cb7-cf54-4dfb-84b1-d34b7feb54aa-1-3&quot; data-index=&quot;4.&quot;&gt;
